n, m = map(int, input().split())
edges = [list(map(int, input().split())) for _ in range(m)]

adj = [[] for _ in range(n + 1)]
for u, v in edges:
    adj[u].append(v)
radj = [[] for _ in range(n + 1)]
for u, v in edges:
    radj[v].append(u)

def flood(graph, start, seen):
    seen[start] = True
    stack = [start]
    count = 1
    while stack:
        u = stack.pop()
        for v in graph[u]:
            if not seen[v]:
                seen[v] = True
                count += 1
                stack.append(v)
    return count

visited = [False] * (n + 1)
last = 0
for v in range(1, n + 1):
    if not visited[v]:
        last = v
        flood(adj, v, visited)
if flood(adj, last, [False] * (n + 1)) != n:
    print(0)
else:
    print(flood(radj, last, [False] * (n + 1)))

