#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> edges(m, vector<long long>(2));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> edges[i][j];
        }
    }

    vector<vector<int>> adj(n + 1);
    for (const vector<long long>& e : edges) adj[e[0]].push_back((int)e[1]);
    vector<vector<int>> radj(n + 1);
    for (const vector<long long>& e : edges) radj[e[1]].push_back((int)e[0]);
    auto flood = [&](const vector<vector<int>>& graph, int start, vector<char>& seen) {
        seen[start] = 1;
        vector<int> stack = {start};
        long long count = 1;
        while (!stack.empty()) {
            int u = stack.back();
            stack.pop_back();
            for (int v : graph[u]) {
                if (!seen[v]) {
                    seen[v] = 1;
                    count++;
                    stack.push_back(v);
                }
            }
        }
        return count;
    };
    vector<char> visited(n + 1, 0);
    int last = 0;
    for (int v = 1; v <= n; v++) {
        if (!visited[v]) {
            last = v;
            flood(adj, v, visited);
        }
    }
    vector<char> first(n + 1, 0), second(n + 1, 0);
    if (flood(adj, last, first) != n) cout << 0 << "\n";
    else cout << flood(radj, last, second) << "\n";

    return 0;
}

