import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static long flood(List<List<Integer>> graph, int start, boolean[] seen) {
        seen[start] = true;
        ArrayList<Integer> stack = new ArrayList<>();
        stack.add(start);
        long count = 1;
        while (!stack.isEmpty()) {
            int u = stack.remove(stack.size() - 1);
            for (int v : graph.get(u)) {
                if (!seen[v]) {
                    seen[v] = true;
                    count++;
                    stack.add(v);
                }
            }
        }
        return count;
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long m = Long.parseLong(next());
        long[][] edges = new long[(int) m][2];
        for (int i = 0; i < edges.length; i++) {
            for (int j = 0; j < edges[i].length; j++) {
                edges[i][j] = Long.parseLong(next());
            }
        }

        int nodes = (int) n;
        List<List<Integer>> adj = new ArrayList<>();
        for (int v = 0; v <= nodes; v++) adj.add(new ArrayList<>());
        for (long[] e : edges) adj.get((int) e[0]).add((int) e[1]);
        List<List<Integer>> radj = new ArrayList<>();
        for (int v = 0; v <= nodes; v++) radj.add(new ArrayList<>());
        for (long[] e : edges) radj.get((int) e[1]).add((int) e[0]);
        boolean[] visited = new boolean[nodes + 1];
        int last = 0;
        for (int v = 1; v <= nodes; v++) {
            if (!visited[v]) {
                last = v;
                flood(adj, v, visited);
            }
        }
        long reach = flood(adj, last, new boolean[nodes + 1]);
        System.out.println(reach != nodes ? 0 : flood(radj, last, new boolean[nodes + 1]));
    }
}
